import { useEffect, useMemo, useState } from 'react';
import { addDoc, collection, deleteDoc, doc, onSnapshot, orderBy, query, serverTimestamp, setDoc, updateDoc } from 'firebase/firestore';
import { createUserWithEmailAndPassword, onAuthStateChanged, sendPasswordResetEmail, signInWithEmailAndPassword, signInWithPopup, signOut, updateProfile, type User } from 'firebase/auth';
import { addDays, differenceInCalendarDays, format, parseISO, startOfDay, subDays } from 'date-fns';
import { Activity, Archive, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, CalendarDays, Check, Clock3, Command, Download, Flame, Focus, House, KeyRound, LayoutDashboard, ListTodo, LoaderCircle, LockKeyhole, LogOut, Menu, MoreHorizontal, Plus, Search, Settings, ShieldCheck, Sparkles, Target, Trash2, TrendingUp, UserRound, X } from 'lucide-react';
import { auth, db, firebaseReady, googleProvider } from './firebase';
import { deleteObject, getBlob, ref as storageRef, uploadBytes } from 'firebase/storage';
import { storage } from './firebase';
import { useLocation, useNavigate } from 'react-router-dom';
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis } from 'recharts';

type Page = 'Command Center'|'Operation 90'|'To-do List'|'Intelligence Archive'|'Performance Report'|'Developer Terminal'|'System Configuration';
type Day = { date: string; studyHours: number; chapters: string; topics: string; notes: string; rating: number; status: 'Not started'|'In progress'|'Completed'|'Missed'; updatedAt?: unknown };
type Task = { id: string; title: string; description?: string; dueDate?: string; priority?: string; status?: string; category?: string; createdAt?: { seconds: number }|string; completedAt?: { seconds: number }|string; missionDay?: number };
type Attachment = { name:string; path:string; size:number };
type Note = { id: string; title: string; body: string; pinned?: boolean; attachments?:Attachment[]; updatedAt?: unknown };
const nav: { name: Page; icon: typeof Command }[] = [
  { name: 'Command Center', icon: LayoutDashboard }, { name: 'Operation 90', icon: Target },
  { name: 'To-do List', icon: ListTodo }, { name: 'Intelligence Archive', icon: Archive },
  { name: 'Performance Report', icon: TrendingUp }, { name: 'Developer Terminal', icon: KeyRound }, { name: 'System Configuration', icon: Settings },
];
const pageLabels: Partial<Record<Page,string>> = { 'Intelligence Archive':'Study Notes', 'Performance Report':'Progress', 'Developer Terminal':'API Access', 'System Configuration':'Account & Settings' };
const pageLabel = (value:Page) => pageLabels[value] || value;
const today = format(new Date(), 'yyyy-MM-dd');
const stamp = (v?: Task['createdAt']) => typeof v === 'string' ? new Date(v) : v?.seconds ? new Date(v.seconds * 1000) : new Date(0);

export default function App() {
  const location = useLocation(), navigate = useNavigate();
  const pageForPath = (path:string):Page => nav.find(item => `/${item.name.toLowerCase().replace(/ /g,'-')}` === path)?.name || 'Command Center';
  const [user, setUser] = useState<User|null>(null), [page, setPage] = useState<Page>(()=>pageForPath(location.pathname));
  const [days, setDays] = useState<Record<string,Day>>({}), [tasks, setTasks] = useState<Task[]>([]), [notes, setNotes] = useState<Note[]>([]), [settings, setSettings] = useState({ startDate: today, missionDuration: 90, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone });
  const [selectedDate, setSelectedDate] = useState(today), [loading, setLoading] = useState(true), [authBusy, setAuthBusy] = useState(false), [mobileOpen, setMobileOpen] = useState(false), [toast, setToast] = useState(''), [filter, setFilter] = useState('All to-dos'), [search, setSearch] = useState('');
  const [showTask, setShowTask] = useState(false), [editingTask, setEditingTask] = useState<Task|null>(null), [showNote, setShowNote] = useState(false), [editingNote, setEditingNote] = useState<Note|null>(null);
  useEffect(() => setPage(pageForPath(location.pathname)), [location.pathname]);
  useEffect(() => { if (!auth) { setLoading(false); return; } return onAuthStateChanged(auth, u => { setUser(u); setLoading(false); }); }, []);
  useEffect(() => {
    if (!db || !user) { setDays({}); setTasks([]); setNotes([]); return; }
    const stopDays = onSnapshot(collection(db, 'users', user.uid, 'days'), snap => { const next: Record<string,Day> = {}; snap.forEach(d => { next[d.id] = d.data() as Day; }); setDays(next); }, () => flash('Could not load mission journals'));
    const stopTasks = onSnapshot(query(collection(db, 'users', user.uid, 'tasks'), orderBy('createdAt', 'desc')), snap => setTasks(snap.docs.map(d => ({ id: d.id, ...d.data() } as Task))), () => flash('Could not load to-do list'));
    const stopNotes = onSnapshot(query(collection(db, 'users', user.uid, 'notes'), orderBy('updatedAt', 'desc')), snap => setNotes(snap.docs.map(d => ({ id: d.id, ...d.data() } as Note))), () => flash('Could not load archive'));
    const stopSettings = onSnapshot(doc(db, 'users', user.uid, 'settings', 'profile'), snap => { if (snap.exists()) setSettings(s => ({ ...s, ...snap.data() })); });
    return () => { stopDays(); stopTasks(); stopNotes(); stopSettings(); };
  }, [user]);
  function flash(s: string) { setToast(s); window.setTimeout(() => setToast(''), 2600); }
  const missionStart = parseISO(settings.startDate || today), dayIndex = differenceInCalendarDays(startOfDay(new Date()), startOfDay(missionStart)) + 1;
  const missionDays = Array.from({ length: Math.max(1, Math.min(90, Number(settings.missionDuration)||90)) }, (_, i) => ({ number: i+1, date: format(addDays(missionStart, i), 'yyyy-MM-dd') }));
  const completed = Object.values(days).filter(d => d.status === 'Completed').length;
  const missionHours = Object.values(days).reduce((n,d) => n + (Number(d.studyHours)||0), 0);
  const todayDay = days[today]; const todayTasks = tasks.filter(t => t.status !== 'Completed' && (!t.dueDate || t.dueDate <= today));
  const streak = useMemo(() => { let n=0, date=today; while (days[date]?.status==='Completed') { n++; date=format(subDays(parseISO(date),1),'yyyy-MM-dd'); } return n; }, [days]);
  const avgRating = useMemo(() => { const rated=Object.values(days).filter(d => d.rating>0); return rated.length ? (rated.reduce((a,d)=>a+d.rating,0)/rated.length).toFixed(1) : '—'; }, [days]);
  async function saveDay(date: string, patch: Partial<Day>) { if (!db || !user) return; const prior=days[date] || { date, studyHours:0, chapters:'', topics:'', notes:'', rating:0, status:'Not started' as const }; await setDoc(doc(db,'users',user.uid,'days',date), { ...prior, ...patch, date, updatedAt:serverTimestamp() }, { merge:true }); }
  async function addTask(data: Partial<Task>) { if (!db || !user) return; await addDoc(collection(db,'users',user.uid,'tasks'), { ...data, status:'Open', createdAt:serverTimestamp() }); setShowTask(false); flash('To-do added'); }
  async function editTask(data: Partial<Task>) { if (!db || !user || !editingTask) return; await updateDoc(doc(db,'users',user.uid,'tasks',editingTask.id), data); setShowTask(false);setEditingTask(null);flash('To-do updated'); }
  async function toggleTask(t: Task) { if (!db || !user) return; await updateDoc(doc(db,'users',user.uid,'tasks',t.id), { status:t.status==='Completed'?'Open':'Completed', ...(t.status==='Completed'?{}:{completedAt:serverTimestamp()}) }); }
  async function addNote(data: {title:string;body:string;pinned:boolean;files:File[]}) { if (!db || !user) return; const noteRef=editingNote?doc(db,'users',user.uid,'notes',editingNote.id):doc(collection(db,'users',user.uid,'notes')); const attachments=[...(editingNote?.attachments||[])]; if(data.files.length&&!storage)throw new Error('Firebase Storage is not configured'); for(const file of data.files){if(file.size>20*1024*1024)throw new Error(`${file.name} exceeds the 20 MB attachment limit`);const path=`users/${user.uid}/notes/${noteRef.id}/${crypto.randomUUID()}-${file.name.replace(/[^\w.-]/g,'_')}`;await uploadBytes(storageRef(storage!,path),file);attachments.push({name:file.name,path,size:file.size});}const {files,...content}=data;const payload={...content,attachments,updatedAt:serverTimestamp()};if(editingNote)await updateDoc(noteRef,payload);else await setDoc(noteRef,{...payload,createdAt:serverTimestamp()});setShowNote(false);setEditingNote(null);flash('Archive updated'); }
  async function downloadAttachment(file:Attachment){if(!storage)return;try{const blob=await getBlob(storageRef(storage,file.path));const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=file.name;link.click();URL.revokeObjectURL(link.href);}catch{flash('Could not download attachment');}}
  async function saveSettings(next: typeof settings) { setSettings(next); if (db && user) await setDoc(doc(db,'users',user.uid,'settings','profile'),next,{merge:true}); flash('Configuration saved'); }
  async function exportData(kind: 'json'|'csv') {
    try {
      const csvCell=(v:unknown)=>`"${String(v??'').replace(/"/g,'""')}"`;
      let body: string;
      if (kind==='json') {
        flash('Preparing complete progress backup…');
        const backupNotes=[];
        for (const note of notes) {
          const attachments=[];
          for (const file of note.attachments||[]) {
            if (!storage) throw new Error('Firebase Storage is unavailable, so attached files cannot be included.');
            const blob=await getBlob(storageRef(storage,file.path));
            const dataUrl=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error(`Could not read ${file.name}`));reader.readAsDataURL(blob);});
            attachments.push({...file,contentType:blob.type||'application/octet-stream',dataUrl});
          }
          backupNotes.push({...note,attachments});
        }
        const allDays=missionDays.map(day=>{const saved=days[day.date];return saved?{...saved,number:day.number}:{date:day.date,number:day.number,studyHours:0,chapters:'',topics:'',notes:'',rating:0,status:'Not started'};});
        body=JSON.stringify({format:'ENDGAME progress backup',version:1,exportedAt:new Date().toISOString(),account:{uid:user?.uid||null,email:user?.email||null,displayName:user?.displayName||null},plan:settings,missionDays:allDays,todos:tasks,notes:backupNotes},null,2);
      } else {
        body=['type,date,title,details,status',...Object.values(days).map(d=>['day',d.date,`${d.studyHours||0}h`,d.chapters||d.notes||'',d.status].map(csvCell).join(',')),...tasks.map(t=>['task',t.dueDate||'',t.title,t.description||'',t.status||'Open'].map(csvCell).join(',')),...notes.map(n=>['note','',n.title,n.body,n.pinned?'pinned':''].map(csvCell).join(','))].join('\n');
      }
      const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type:kind==='json'?'application/json':'text/csv'}));a.download=`endgame-progress-${today}.${kind}`;a.click();window.setTimeout(()=>URL.revokeObjectURL(a.href),1000);flash(kind==='json'?'Complete progress backup downloaded':'Progress summary downloaded');
    } catch (error) { flash(error instanceof Error?`Export failed: ${error.message}`:'Export failed. Try again.'); }
  }
  if (loading) return <div className="boot"><img className="brand-image" src="/icon.png" alt="" /><LoaderCircle className="spin" size={18}/><span>ESTABLISHING SECURE CONNECTION</span></div>;
  if (!firebaseReady) return <Setup />;
  if (!user) return <AuthScreen busy={authBusy} setBusy={setAuthBusy} />;
  const go=(p:Page)=>{setPage(p);navigate(p==='Command Center'?'/':`/${p.toLowerCase().replace(/ /g,'-')}`);setMobileOpen(false);};
  return <div className="shell">
    <aside className={`sidebar ${mobileOpen?'open':''}`}><div className="brand"><img className="brand-image" src="/icon.png" alt="" /><div><b>ENDGAME</b><span>STUDY PLANNER</span></div><button type="button" aria-label="Close navigation" className="icon-btn mobile-close" onClick={()=>setMobileOpen(false)}><X size={17}/></button></div>
      <div className="nav-label">Your study plan</div><nav aria-label="Main navigation">{nav.map(({name,icon:Icon})=><button key={name} onClick={()=>go(name)} className={`nav-item ${page===name?'active':''}`} aria-current={page===name?'page':undefined}><Icon size={17}/><span>{pageLabel(name)}</span></button>)}</nav>
      <div className="sidebar-bottom"><button className="user-card" onClick={()=>go('System Configuration')}><div className="avatar">{(user.displayName||user.email||'U')[0].toUpperCase()}</div><span><b>{user.displayName||'Student'}</b><small>Account</small></span><MoreHorizontal size={17}/></button><button className="logout" onClick={()=>auth&&signOut(auth)}><LogOut size={15}/> Sign out</button></div>
    </aside>
    {mobileOpen&&<div className="scrim" onClick={()=>setMobileOpen(false)}/>}
    <main className="main"><header className="topbar"><button type="button" aria-label="Open navigation" className="icon-btn mobile-menu" onClick={()=>setMobileOpen(true)}><Menu size={19}/></button>{page==='Command Center'&&<button type="button" className="primary" onClick={()=>{setSelectedDate(today);go('Operation 90')}}><Focus size={16}/> Open Today’s Journal</button>}</header>
      <div className="content">{page==='Command Center'&&<Dashboard {...{dayIndex,completed,missionHours,avgRating,streak,todayTasks,todayDay,missionDays,days,tasks,setSelectedDate,go}}/>}
        {page==='Operation 90'&&<Operation {...{missionDays,days,selectedDate,setSelectedDate,saveDay,flash}}/>}
        {page==='To-do List'&&<TasksPage {...{tasks,filter,setFilter,search,setSearch,toggleTask,setShowTask,setEditingTask,flash,deleteTask:async(id:string)=>{if(!db||!user)return;await deleteDoc(doc(db,'users',user.uid,'tasks',id));flash('To-do deleted');}}}/>}
        {page==='Intelligence Archive'&&<NotesPage {...{notes,setShowNote,setEditingNote,downloadAttachment,flash,deleteNote:async(id:string)=>{if(!db||!user)return;const note=notes.find(n=>n.id===id);for(const file of note?.attachments||[])if(storage)await deleteObject(storageRef(storage,file.path)).catch(()=>{});await deleteDoc(doc(db,'users',user.uid,'notes',id));flash('Note deleted');}}}/>}
        {page==='Performance Report'&&<Performance {...{days,tasks,missionDays,missionHours,completed,avgRating,streak}}/>}
        {page==='Developer Terminal'&&<Developer {...{flash,user}}/>}
        {page==='System Configuration'&&<Configuration {...{user,settings,saveSettings,exportData}}/>}
      </div>
    </main>
    <nav className="mobile-tabbar" aria-label="Primary navigation">{[{label:'Home',page:'Command Center' as Page,icon:House},{label:'Mission',page:'Operation 90' as Page,icon:Target},{label:'To-do',page:'To-do List' as Page,icon:ListTodo},{label:'Account',page:'System Configuration' as Page,icon:UserRound}].map(({label,page:target,icon:Icon})=><button key={label} className={page===target?'selected':''} onClick={()=>go(target)} aria-label={label} aria-current={page===target?'page':undefined}><Icon size={21} strokeWidth={page===target?2.3:1.8}/><span>{label}</span></button>)}</nav>
    {showTask&&<TaskModal initial={editingTask} close={()=>{setShowTask(false);setEditingTask(null)}} save={editingTask?editTask:addTask}/>}{showNote&&<NoteModal initial={editingNote} close={()=>{setShowNote(false);setEditingNote(null)}} save={addNote}/>}
    {toast&&<div className="toast"><Check size={15}/>{toast}</div>}
  </div>;
}

function Setup(){return <div className="auth-wrap"><div className="auth-card setup"><img className="brand-image" src="/icon.png" alt="" /><p className="eyebrow">INITIAL CONFIGURATION</p><h1>Connect your command center.</h1><p className="muted">Add your Firebase web app settings to start ENDGAME. Your credentials stay in your environment and are never included in source code.</p><div className="setup-steps"><b>01</b><span>Create a Firebase project and register a Web app.</span><b>02</b><span>Enable Email/Password and Google under Authentication.</span><b>03</b><span>Copy <code>.env.example</code> to <code>.env.local</code> and fill in your Firebase config.</span><b>04</b><span>Deploy Firestore rules from <code>firestore.rules</code>.</span></div><p className="setup-foot"><ShieldCheck size={15}/> Auth, database, storage and API functions are ready for your project configuration.</p></div></div>}

function AuthScreen({busy,setBusy}:{busy:boolean;setBusy:(v:boolean)=>void}){const [mode,setMode]=useState<'login'|'register'|'reset'>('login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[error,setError]=useState('');async function submit(e:React.FormEvent){e.preventDefault();if(!auth)return;setBusy(true);setError('');try{if(mode==='reset'){await sendPasswordResetEmail(auth,email);setError('Reset link sent. Check your inbox.');}else if(mode==='register'){const cred=await createUserWithEmailAndPassword(auth,email,password);if(name)await updateProfile(cred.user,{displayName:name});}else await signInWithEmailAndPassword(auth,email,password);}catch(err){setError(err instanceof Error?err.message:'Authentication failed');}finally{setBusy(false);}}async function google(){if(!auth)return;setBusy(true);setError('');try{await signInWithPopup(auth,googleProvider);}catch(err){setError(err instanceof Error?err.message:'Google sign-in failed');}finally{setBusy(false);}}
return <div className="auth-wrap"><div className="auth-backdrop"/><div className="auth-brand"><img className="brand-image" src="/icon.png" alt="" /><b>ENDGAME</b><span>A study plan that fits your day.</span></div><div className="auth-card"><div className="auth-class"><span className="live-dot"/> SECURE ACCESS</div><h1>{mode==='register'?'Create your account':mode==='reset'?'Reset password':'Welcome back.'}</h1><p className="muted">{mode==='reset'?'We’ll send a recovery link to your email.':'Sign in to continue with your study plan.'}</p><form onSubmit={submit}>{mode==='register'&&<label>YOUR NAME<input value={name} onChange={e=>setName(e.target.value)} placeholder="Your name" required/></label>}<label>EMAIL ADDRESS<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com" required/></label>{mode!=='reset'&&<label>PASSWORD<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 6 characters" minLength={6} required/></label>}{error&&<p className="auth-error">{error}</p>}<button className="primary wide" disabled={busy}>{busy?<LoaderCircle className="spin" size={16}/>:null}{mode==='register'?'Create account':mode==='reset'?'Send reset link':'Sign in'}<ArrowRight size={16}/></button></form>{mode==='login'&&<><div className="or"><span/>OR<span/></div><button className="secondary wide" onClick={google} disabled={busy}><span className="google-g">G</span> Continue with Google</button></>}<div className="auth-switch">{mode==='login'?<><button onClick={()=>setMode('reset')}>Forgot password?</button><span>New here?</span><button onClick={()=>setMode('register')}>Create account</button></>:<button onClick={()=>setMode('login')}>← Return to sign in</button>}</div><div className="auth-secure"><LockKeyhole size={13}/> Encrypted connection · Your workspace is private</div></div><div className="auth-copyright">ENDGAME SYSTEMS <span>•</span> EST. 2025</div></div>}

function PageHead({kicker,title,description,action}:{kicker:string;title:string;description:string;action?:React.ReactNode}){return <div className="page-head"><div><div className="eyebrow"><span className="gold-line"/>{kicker}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>}
function Stat({label,value,meta,icon:Icon,trend}:{label:string;value:string|number;meta:string;icon:typeof Activity;trend?:'up'|'down'}){return <div className="stat-card"><div className="stat-head"><span>{label}</span><Icon size={16}/></div><div className="stat-value">{value}</div><div className={`stat-meta ${trend||''}`}>{trend==='up'?<ArrowUpRight size={13}/>:trend==='down'?<ArrowDownRight size={13}/>:null}{meta}</div></div>}
function Dashboard(p: any) {
  const {dayIndex,completed,missionHours,avgRating,streak,todayTasks,todayDay,missionDays,days,tasks,setSelectedDate,go}=p;
  const current=Math.max(1,Math.min(missionDays.length,dayIndex));
  const [phase,setPhase]=useState(Math.min(2,Math.floor((current-1)/30)));
  const [inspectedDate,setInspectedDate]=useState<string|null>(null);
  const todayDone=tasks.filter((t:Task)=>t.status==='Completed'&&t.completedAt&&format(stamp(t.completedAt),'yyyy-MM-dd')===today).length;
  const bestStreak=missionDays.reduce((state:{run:number;best:number},day:any)=>{const run=days[day.date]?.status==='Completed'?state.run+1:0;return {run,best:Math.max(state.best,run)}},{run:0,best:0}).best;
  const phases=[0,1,2].map(i=>missionDays.slice(i*30,(i+1)*30));
  const counts=phases.map(list=>list.reduce((sum:{completed:number;active:number;missed:number},d:any)=>{const s=days[d.date]?.status;return {...sum,completed:sum.completed+(s==='Completed'?1:0),active:sum.active+(s==='In progress'?1:0),missed:sum.missed+(s==='Missed'?1:0)}},{completed:0,active:0,missed:0}));
  const selectedDay=missionDays.find((d:any)=>d.date===inspectedDate);
  const selectedEntry=selectedDay?days[selectedDay.date]:undefined;
  return <>
    <PageHead kicker={format(new Date(),'EEEE, MMMM d')} title="Command Center" description="Your study plan, and the next step." />
    <section className="today-focus" aria-labelledby="today-focus-title">
      <div className="today-focus-copy"><div className="focus-date"><span className={`status-pill ${(todayDay?.status||'Not started').toLowerCase().replace(' ','-')}`} />Today · Day {current} of {missionDays.length}</div><h2 id="today-focus-title">Make today count.</h2><p>{todayDay?.status==='Completed'?'You showed up today. Take a moment to note what worked.':'A little progress is enough to keep your mission moving.'}</p><div className="focus-status">{todayDay?.status||'Not started'} · {todayTasks.length} to-dos left today</div></div>
      <div className="today-hours"><span>{Number(todayDay?.studyHours||0).toFixed(todayDay?.studyHours%1?1:0)}<small>h</small></span><b>Hours logged</b></div>
    </section>
    <section className="stats-grid" aria-label="Mission summary"><Stat label="Mission Progress" value={`${Math.round(Math.min(90,completed)/90*100)}%`} meta={`${Math.min(90,completed)}/90 days · ${Math.max(0,90-completed)} days remaining`} icon={Target}/><Stat label="Study Hours" value={missionHours.toFixed(1)} meta="hrs logged" icon={Clock3}/><Stat label="Current Streak" value={`${streak} days`} meta={`Best streak: ${bestStreak}d`} icon={Flame} trend={streak?'up':undefined}/><Stat label="Avg Daily Rating" value={`${avgRating} / 10`} meta={avgRating==='—'?'No ratings logged yet':'Across rated days'} icon={Activity}/></section>
    <section className="journey-section" aria-labelledby="journey-title">
      <div className="section-row journey-heading"><div><div className="eyebrow">Your 90-day journey</div><h2 className="section-title" id="journey-title">Steady progress, one day at a time.</h2></div><span className="journey-count">{completed} of 90 days complete</span></div>
      <div className="phase-picker" role="group" aria-label="Mission phases">{phases.map((_list,i)=><button type="button" key={i} className={`phase-choice ${phase===i?'active':''}`} aria-pressed={phase===i} onClick={()=>{setPhase(i);setInspectedDate(null)}}><span>Days {i*30+1}–{Math.min((i+1)*30,missionDays.length)}</span><small>{counts[i].completed} complete · {counts[i].missed} missed</small></button>)}</div>
      <section className="progress-card phase-card" aria-label={`Phase ${phase+1}, days ${phase*30+1} to ${Math.min((phase+1)*30,missionDays.length)}`}>
        <div className="phase-head"><div><span className="card-kicker">Phase {phase+1}</span><h3>{phase===0?'Build the rhythm':phase===1?'Find your pace':'Finish with confidence'}</h3></div><span className="phase-range">Days {phase*30+1}–{Math.min((phase+1)*30,missionDays.length)}</span></div>
        <div className="phase-days" role="group" aria-label="Choose a mission day">{phases[phase].map((d:any)=>{const entry=days[d.date],state=entry?.status||'Not started',isCurrent=d.date===today,isSelected=d.date===inspectedDate;return <button type="button" key={d.date} title={`Day ${d.number}, ${format(parseISO(d.date),'MMMM d')}, ${state}`} className={`day-node ${state.toLowerCase().replace(' ','-')} ${isCurrent?'today':''} ${isSelected?'selected':''}`} onClick={()=>setInspectedDate(isSelected?null:d.date)} aria-pressed={isSelected} aria-controls="day-inspector" aria-label={`Day ${d.number}, ${format(parseISO(d.date),'MMMM d')}, ${state}${isCurrent?', today':''}`}><span>{d.number}</span></button>})}</div>
        {selectedDay&&<div className="day-inspector" id="day-inspector" aria-live="polite"><div><span className="card-kicker">Day {selectedDay.number} · {format(parseISO(selectedDay.date),'EEEE, MMMM d')}</span><p>{selectedEntry?.notes?.trim()||selectedEntry?.topics?.trim()||selectedEntry?.chapters?.trim()||'No journal note yet.'}</p><div className="inspector-stats"><span>{Number(selectedEntry?.studyHours||0).toFixed(1)} hours logged</span><span>Focus rating {selectedEntry?.rating||'—'}{selectedEntry?.rating?'/10':''}</span><span>{selectedEntry?.status||'Not started'}</span></div></div><button type="button" className="secondary compact" onClick={()=>{setSelectedDate(selectedDay.date);go('Operation 90')}}>Open journal <ArrowRight size={14}/></button></div>}
      </section>
      <div className="mission-legend" aria-label="Mission day statuses"><span><i className="done"/>Completed</span><span><i className="partial"/>In progress</span><span><i className="missed"/>Missed</span><span><i className="future"/>Upcoming</span><span><i className="current"/>Today</span></div>
    </section>
    <div className="lower-grid"><section className="panel today-panel"><div className="panel-head"><div><span className="card-kicker">Today</span><h3>Daily summary</h3></div><span className="date-chip">{format(new Date(),'MMM d')}</span></div><div className="today-metrics"><div><span>Hours logged</span><b>{todayDay?.studyHours||0}<small>h</small></b></div><div><span>Focus rating</span><b>{todayDay?.rating||'—'}<small>{todayDay?.rating?'/10':''}</small></b></div><div><span>To-dos done</span><b>{todayDone}<small>/{todayDone+todayTasks.length}</small></b></div></div><div className="today-bottom"><span><span className={`status-pill ${(todayDay?.status||'Not started').toLowerCase().replace(' ','-')}`}/>{todayDay?.status||'Not started'}</span></div></section><section className="panel quick-panel"><div className="panel-head"><div><span className="card-kicker">To-do list</span><h3>Next up</h3></div><button className="text-action" onClick={()=>go('To-do List')}>View all <ArrowRight size={13}/></button></div>{tasks.filter((t:Task)=>t.status!=='Completed').slice(0,3).length===0?<div className="empty-small"><Check size={15}/> All done for now. Enjoy the break.</div>:tasks.filter((t:Task)=>t.status!=='Completed').slice(0,3).map((t:Task)=><div className="quick-task" key={t.id}><span className={`priority-dot ${(t.priority||'Normal').toLowerCase()}`}/><span>{t.title}<small>{t.dueDate?`Due ${format(parseISO(t.dueDate),'MMM d')}`:t.category||'No deadline'}</small></span><button className="icon-btn" aria-label={`View ${t.title}`} onClick={()=>go('To-do List')}><ArrowRight size={14}/></button></div>)}</section></div>
    <footer className="footer"><span>Your study plan</span><span>A plan that fits your day.</span></footer>
  </>;
}
function Operation(p:any){const {missionDays,days,selectedDate,setSelectedDate,saveDay,flash}=p;const selected=missionDays.find((d:any)=>d.date===selectedDate)||missionDays[0];const entry:Day=days[selected?.date]||{date:selected?.date,studyHours:0,chapters:'',topics:'',notes:'',rating:0,status:'Not started'};const dayNum=selected?.number||1;const prev=()=>setSelectedDate(format(subDays(parseISO(selected.date),1),'yyyy-MM-dd'));const next=()=>setSelectedDate(format(addDays(parseISO(selected.date),1),'yyyy-MM-dd'));async function field(k:keyof Day,v:any){await saveDay(selected.date,{[k]:v});flash('Journal saved');}
return <><PageHead kicker="YOUR STUDY JOURNAL" title="Operation 90" description="Record study time, topics, and how the day felt." action={<div className="day-nav"><button className="secondary compact" onClick={prev} disabled={dayNum<=1}>← Previous</button><button className="secondary compact" onClick={next} disabled={dayNum>=missionDays.length}>Next →</button></div>}/><div className="op-layout"><div className="op-main"><section className="journal-card"><div className="journal-head"><div><span className="card-kicker">DAILY JOURNAL</span><h2>Day {String(dayNum).padStart(2,'0')} <span>/ {missionDays.length}</span></h2><div className="journal-date"><CalendarDays size={14}/>{format(parseISO(selected.date),'EEEE, MMMM d, yyyy')}</div></div><select className="status-select" value={entry.status} onChange={e=>field('status',e.target.value)}>{['Not started','In progress','Completed','Missed'].map(s=><option key={s}>{s}</option>)}</select></div><div className="journal-fields"><label className="field-label">STUDY HOURS<div className="input-suffix"><input type="number" min="0" max="24" step="0.25" value={entry.studyHours||0} onChange={e=>field('studyHours',Number(e.target.value))}/><span>HRS</span></div></label><label className="field-label">Chapters studied<textarea rows={4} placeholder={'Physics:\n• Electrostatics\n• Electric potential\n\nChemistry:\n• Chemical bonding'} value={entry.chapters||''} onChange={e=>saveDay(selected.date,{chapters:e.target.value})} onBlur={()=>flash('Journal saved')}/></label><label className="field-label">Topics covered<textarea rows={3} placeholder="Key concepts, techniques, and questions to revisit..." value={entry.topics||''} onChange={e=>saveDay(selected.date,{topics:e.target.value})} onBlur={()=>flash('Journal saved')}/></label><label className="field-label">Notes<textarea rows={4} placeholder="What worked? What would you change tomorrow?" value={entry.notes||''} onChange={e=>saveDay(selected.date,{notes:e.target.value})} onBlur={()=>flash('Journal saved')}/></label></div><div className="journal-foot"><span><ShieldCheck size={14}/> Automatically saved as you type</span><span>LAST UPDATED · {entry.updatedAt?'JUST NOW':'—'}</span></div></section><section className="rating-card"><div><span className="card-kicker">END OF DAY REVIEW</span><h3>How did you show up today?</h3><p>Rate your focus, effort, and follow-through.</p></div><div className="rating-picker">{Array.from({length:10},(_,i)=><button key={i} className={entry.rating===i+1?'selected':''} onClick={()=>field('rating',i+1)} aria-label={`Rate ${i+1} out of 10`}>{i+1}</button>)}</div><div className="rating-captions"><span>NEEDS WORK</span><span>EXCEPTIONAL</span></div></section></div><aside className="op-aside"><section className="panel day-card"><div className="card-kicker">MISSION POSITION</div><div className="day-number">{String(dayNum).padStart(2,'0')}<small>/90</small></div><div className="progress-track"><i style={{width:`${dayNum/90*100}%`}}/></div><p>{Math.max(0,90-dayNum)} days left in this campaign.</p><div className="op-divider"/><div className="aside-stat"><span>DAY STATUS</span><b><span className={`status-pill ${entry.status.toLowerCase().replace(' ','-')}`}/>{entry.status}</b></div><div className="aside-stat"><span>STUDY TIME</span><b>{entry.studyHours||0} hrs</b></div></section><section className="panel"><div className="panel-head"><div><span className="card-kicker">Mission day</span><h3>Choose a day</h3></div></div><label className="mission-day-picker">Go to day<select value={selected.date} onChange={e=>setSelectedDate(e.target.value)}>{[0,1,2].map(phase=><optgroup key={phase} label={`Days ${phase*30+1}–${Math.min((phase+1)*30,missionDays.length)}`}>{missionDays.slice(phase*30,(phase+1)*30).map((d:any)=><option key={d.date} value={d.date}>Day {d.number} · {format(parseISO(d.date),'MMM d')} · {days[d.date]?.status||'Not started'}</option>)}</optgroup>)}</select></label></section></aside></div><footer className="footer"><span>FIELD JOURNAL <i/> DAY {dayNum} OF 90</span><span>WRITE IT DOWN. MAKE IT REAL.</span></footer></>}

function TasksPage(p:any){
  const {tasks,filter,setFilter,search,setSearch,toggleTask,setShowTask,setEditingTask,deleteTask}=p;
  const filters=['Today','Upcoming','Overdue','Completed','10-day history','All to-dos'];
  const now=new Date(), tenDays=subDays(startOfDay(now),9);
  const visible=tasks.filter((t:Task)=>{const created=stamp(t.createdAt),isDone=t.status==='Completed';if(filter==='Today')return t.dueDate===today&&!isDone;if(filter==='Upcoming')return !!t.dueDate&&t.dueDate>today&&!isDone;if(filter==='Overdue')return !!t.dueDate&&t.dueDate<today&&!isDone;if(filter==='Completed')return isDone;if(filter==='10-day history')return created>=tenDays||stamp(t.completedAt)>=tenDays;return true;}).filter((t:Task)=>t.title.toLowerCase().includes(search.toLowerCase()));
  function edit(t:Task){setEditingTask(t);setShowTask(true)}
  return <><PageHead kicker="PRIORITIES / EXECUTION" title="To-do List" description="A simple place to capture, organize, and finish what you need to do." action={<button className="primary" onClick={()=>{setEditingTask(null);setShowTask(true)}}><Plus size={16}/> New to-do</button>}/><div className="task-toolbar"><div className="filter-tabs">{filters.map(f=><button key={f} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{f}{f==='10-day history'&&<span className="tab-count">10</span>}</button>)}</div><label className="searchbox"><Search size={15}/><input placeholder="Search to-dos" value={search} onChange={e=>setSearch(e.target.value)}/></label></div>{filter==='10-day history'&&<div className="history-banner"><Clock3 size={16}/><span><b>10-day to-do history</b><small>To-dos created or completed since {format(tenDays,'MMM d, yyyy')}. Past due items remain in your record.</small></span></div>}<div className="task-list">{visible.length===0?<div className="empty-state"><div className="empty-icon"><ListTodo size={23}/></div><h3>{search?'No matching to-dos.':'No to-dos here yet.'}</h3><p>{search?'Try a different search term.':'Add a to-do to make the next move clear.'}</p>{!search&&<button className="secondary" onClick={()=>{setEditingTask(null);setShowTask(true)}}><Plus size={15}/> Add a to-do</button>}</div>:visible.map((t:Task)=><article className={`task-row ${t.status==='Completed'?'completed':''}`} key={t.id}><button className={`task-check ${t.status==='Completed'?'checked':''}`} onClick={()=>toggleTask(t)} aria-label="Mark to-do complete">{t.status==='Completed'&&<Check size={14}/>}</button><div className="task-info"><button className="task-title" onClick={()=>edit(t)}>{t.title}</button>{t.description&&<p>{t.description}</p>}<div className="task-meta"><span className="category-chip">{t.category||'Other'}</span><span className={`priority-label ${(t.priority||'Normal').toLowerCase()}`}><i/>{t.priority||'Normal'}</span>{t.dueDate&&<span className={t.dueDate<today&&t.status!=='Completed'?'overdue-date':''}><CalendarDays size={12}/>{format(parseISO(t.dueDate),'MMM d, yyyy')}</span>}{filter==='10-day history'&&<span>Created {format(stamp(t.createdAt),'MMM d')}</span>}{t.completedAt&&<span><Check size={12}/> Completed {format(stamp(t.completedAt),'MMM d, h:mm a')}</span>}</div></div><span className={`task-status ${t.status==='Completed'?'done':''}`}>{t.status==='Completed'?'COMPLETED':'OPEN'}</span><button className="icon-btn danger-icon" title="Delete to-do" onClick={()=>confirm('Delete this to-do and its history?')&&deleteTask(t.id)}><Trash2 size={14}/></button></article>)}</div><div className="task-summary"><span>{visible.length} {visible.length===1?'to-do':'to-dos'} in view</span><span>To-dos keep their creation and completion dates</span></div><footer className="footer"><span>TO-DO LIST <i/> {tasks.length} TOTAL TO-DOS</span><span>ONE THING AT A TIME.</span></footer></>}function NotesPage(p:any){const {notes,setShowNote,setEditingNote,downloadAttachment,deleteNote}=p;const [q,setQ]=useState('');const filtered=notes.filter((n:Note)=>`${n.title} ${n.body}`.toLowerCase().includes(q.toLowerCase()));return <><PageHead kicker="YOUR NOTES" title="Study Notes" description="Keep notes, useful links, and supporting files in one place." action={<button className="primary" onClick={()=>{setEditingNote(null);setShowNote(true)}}><Plus size={16}/> New note</button>}/><label className="searchbox archive-search"><Search size={15}/><input placeholder="Search notes" value={q} onChange={e=>setQ(e.target.value)}/></label><div className="notes-grid">{filtered.map((n:Note)=><article className="note-card" key={n.id}><div className="note-top"><span className="card-kicker">{n.pinned?'PINNED NOTE':'NOTE'}</span><div><button className="icon-btn" title="Edit note" onClick={()=>{setEditingNote(n);setShowNote(true)}}><MoreHorizontal size={16}/></button><button className="icon-btn danger-icon" title="Delete note" onClick={()=>confirm('Delete this note permanently?')&&deleteNote(n.id)}><Trash2 size={14}/></button></div></div><h3>{n.title}</h3><p>{n.body}</p>{(n.attachments?.length||0)>0&&<div className="note-attachments">{n.attachments!.map((file:Attachment)=><button key={file.path} onClick={()=>downloadAttachment(file)}><Download size={12}/>{file.name}</button>)}</div>}<div className="note-foot"><span>{n.updatedAt?'RECENTLY UPDATED':'JUST ADDED'}</span><button onClick={()=>{setEditingNote(n);setShowNote(true)}}>Open note <ArrowRight size={12}/></button></div></article>)}{filtered.length===0&&<div className="empty-state archive-empty"><div className="empty-icon"><Archive size={23}/></div><h3>{q?'Nothing found.':'The archive is quiet.'}</h3><p>{q?'Try another search.':'Capture the first thought worth keeping.'}</p><button className="secondary" onClick={()=>{setEditingNote(null);setShowNote(true)}}><Plus size={15}/> Write a note</button></div>}</div><footer className="footer"><span>STUDY NOTES <i/> {notes.length} ENTRIES</span><span>THINK CLEARLY. KEEP WHAT MATTERS.</span></footer></>}function Performance(p:any){const {days,tasks,missionDays,missionHours,completed,avgRating,streak}=p;const weekly=Array.from({length:7},(_,i)=>{const date=format(subDays(new Date(),6-i),'yyyy-MM-dd');return {day:format(parseISO(date),'EEE'),hours:days[date]?.studyHours||0,rating:days[date]?.rating||0};});return <><PageHead kicker="Your progress" title="Progress" description="Patterns are useful. Progress is the point." action={<span className="date-chip"><Activity size={13}/> Last 7 days</span>}/><div className="stats-grid report-stats"><Stat label="Days completed" value={`${Math.round(completed/90*100)}%`} meta={`${completed} days logged as complete`} icon={Target}/><Stat label="STUDY HOURS" value={`${missionHours.toFixed(1)}h`} meta="In this 90-day plan" icon={Clock3}/><Stat label="Average rating" value={avgRating} meta="Across rated days" icon={Activity}/><Stat label="Current streak" value={`${streak} days`} meta="Completed days in a row" icon={Flame}/></div><div className="report-grid"><section className="panel chart-card"><div className="panel-head"><div><span className="card-kicker">STUDY HOURS</span><h3>Seven day cadence</h3></div><span className="gold-caption">HOURS / DAY</span></div><ResponsiveContainer width="100%" height={170}><BarChart data={weekly} margin={{top:8,right:8,left:-22,bottom:0}}><CartesianGrid vertical={false} stroke="var(--separator)"/><XAxis dataKey="day" tick={{fill:"var(--muted)",fontSize:9}} axisLine={{stroke:"var(--separator)"}} tickLine={false}/><Tooltip cursor={{fill:"var(--surface-raised)"}} contentStyle={{background:"var(--surface)",border:"1px solid var(--separator)",borderRadius:12,color:"var(--ink)",fontSize:13}}/><Bar dataKey="hours" name="Study hours" fill="var(--accent)" radius={[3,3,0,0]}/></BarChart></ResponsiveContainer></section><section className="panel rating-chart"><div className="panel-head"><div><span className="card-kicker">DAILY RATINGS</span><h3>Effort, reflected</h3></div><span className="gold-caption">OUT OF 10</span></div><div className="rating-bars">{weekly.map(d=><div key={d.day}><span>{d.rating||'—'}</span><i style={{height:`${d.rating*10}%`}}/><small>{d.day.slice(0,1)}</small></div>)}</div></section></div><section className="panel report-timeline"><div className="panel-head"><div><span className="card-kicker">MISSION STATUS</span><h3>Completion breakdown</h3></div><span className="date-chip">{missionDays.length} DAYS</span></div><div className="breakdown"><div><span><i className="done"/>Completed</span><b>{completed}</b></div><div><span><i className="partial"/>In progress</span><b>{Object.values(days).filter((d:any)=>d.status==='In progress').length}</b></div><div><span><i className="missed"/>Missed</span><b>{Object.values(days).filter((d:any)=>d.status==='Missed').length}</b></div><div><span><i className="future"/>Not started</span><b>{Math.max(0,missionDays.length-completed-Object.values(days).filter((d:any)=>d.status==='In progress'||d.status==='Missed').length)}</b></div></div><div className="report-meter"><i style={{width:`${Math.min(100,completed/90*100)}%`}}/></div><p className="report-foot">{tasks.filter((t:Task)=>t.status==='Completed').length} to-dos completed across {tasks.length} to-dos.</p></section><footer className="footer"><span>PERFORMANCE ANALYTICS <i/> LIVE FROM YOUR JOURNALS</span><span>MEASURE. ADJUST. CONTINUE.</span></footer></>}

function Developer(p:any){const {flash,user}=p;const [keys,setKeys]=useState<{id:string;name:string;created:string;lastUsed?:string|null;shown?:string}[]>([]);const [label,setLabel]=useState('');const [busy,setBusy]=useState(false);async function request(path:string,method='GET',body?:unknown){const token=await user.getIdToken();const res=await fetch(path,{method,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const data=await res.json();if(!res.ok)throw new Error(data.error||'Request failed');return data;}useEffect(()=>{request('/api/v1/keys').then(data=>setKeys(data.keys.map((k:any)=>({...k,created:k.createdAt?format(new Date(k.createdAt),'yyyy-MM-dd'):'Recently',lastUsed:k.lastUsedAt})))).catch(()=>{});},[user]);async function create(){if(!label.trim())return;setBusy(true);try{const data=await request('/api/v1/keys','POST',{name:label.trim()});setKeys((old:any[])=>[{id:data.id,name:data.name,created:today,shown:data.key},...old]);setLabel('');flash('Key generated — copy it now.');window.setTimeout(()=>setKeys((v:any[])=>v.map(k=>({...k,shown:undefined}))),30000);}catch(e){flash(e instanceof Error?e.message:'Key creation failed')}finally{setBusy(false)}}async function revoke(id:string){if(!confirm('Revoke this API key? Connected widgets will lose access.'))return;try{await request(`/api/v1/keys/${id}`,'DELETE');setKeys((v:any[])=>v.filter(k=>k.id!==id));flash('API key revoked')}catch(e){flash(e instanceof Error?e.message:'Key revocation failed')}}
return <><PageHead kicker="INTEGRATIONS / ACCESS CONTROL" title="API Access" description="Connect Scriptable and other personal tools."/><div className="api-notice"><ShieldCheck size={19}/><span><b>Read-only access by default.</b><small>Keys are shown once. Keep them private. Configure server credentials before deploying API routes.</small></span><span className="notice-status">API v1 READY</span></div><div className="developer-grid"><section className="panel key-panel"><div className="panel-head"><div><span className="card-kicker">PERSONAL API KEYS</span><h3>Developer access</h3></div><KeyRound size={17}/></div><p className="muted">Generate a key for Scriptable or another trusted client. Revoke access at any time.</p><form className="key-create" onSubmit={e=>{e.preventDefault();create()}}><input value={label} onChange={e=>setLabel(e.target.value)} placeholder="Key name, e.g. iPhone widget"/><button className="primary" type="submit" disabled={busy}><Plus size={14}/> Generate key</button></form>{keys.length===0?<div className="empty-small">No access keys have been created.</div>:keys.map((k:any)=><div className="api-key-row" key={k.id}><div className="key-icon"><KeyRound size={15}/></div><div><b>{k.name}</b><small>Created {k.created} · {k.lastUsed?'Used '+format(new Date(k.lastUsed),'MMM d'):'Never used'} · Read only</small>{k.shown&&<code>{k.shown}</code>}</div><button className="icon-btn danger-icon" title="Revoke key" onClick={()=>revoke(k.id)}><Trash2 size={15}/></button></div>)}</section><section className="panel endpoints-panel"><div className="panel-head"><div><span className="card-kicker">AVAILABLE ROUTES</span><h3>REST endpoints</h3></div><span className="live-chip"><i/> LIVE</span></div>{[['GET','/api/v1/mission','Mission progress and streak'],['GET','/api/v1/today','Today’s journal and tasks'],['GET','/api/v1/tasks','Open task list'],['GET','/api/v1/tasks/history','Last 10 days of task events'],['GET','/api/v1/analytics/weekly','Seven day study stats']].map(r=><div className="endpoint" key={r[1]}><code>{r[0]}</code><b>{r[1]}</b><span>{r[2]}</span></div>)}</section></div><section className="panel docs-card"><div className="panel-head"><div><span className="card-kicker">QUICK START</span><h3>Connect Scriptable</h3></div><button className="text-action" onClick={()=>flash('See SCRIPTABLE.md in your project files')}>Open guide <ArrowRight size={13}/></button></div><pre>{`const req = new Request("https://YOUR-SITE.netlify.app/api/v1/mission");\nreq.headers = { Authorization: "Bearer YOUR_API_KEY" };\nconst data = await req.loadJSON();`}</pre><div className="docs-bottom"><span><LockKeyhole size={13}/> Store the key in Scriptable Keychain</span><span><Activity size={13}/> iOS controls widget refresh frequency</span></div></section><footer className="footer"><span>DEVELOPER TERMINAL <i/> SERVERLESS API</span><span>YOUR DATA. YOUR TOOLS.</span></footer></>}function Configuration(p:any){const {user,settings,saveSettings,exportData}=p;const [draft,setDraft]=useState(settings);useEffect(()=>setDraft(settings),[settings]);return <><PageHead kicker="PREFERENCES / ACCOUNT" title="Account & Settings" description="Manage your study plan and account."/><div className="settings-grid"><section className="panel settings-panel"><div className="panel-head"><div><span className="card-kicker">PLAN</span><h3>Study plan</h3></div><Settings size={17}/></div><label className="field-label">MISSION START DATE<input type="date" value={draft.startDate} onChange={e=>setDraft({...draft,startDate:e.target.value})}/></label><label className="field-label">MISSION DURATION<select value={draft.missionDuration} onChange={e=>setDraft({...draft,missionDuration:Number(e.target.value)})}><option value={90}>90 days</option></select></label><label className="field-label">TIMEZONE<input value={draft.timezone} onChange={e=>setDraft({...draft,timezone:e.target.value})}/></label><button className="primary" onClick={()=>saveSettings(draft)}>Save changes <Check size={15}/></button></section><section className="panel settings-panel"><div className="panel-head"><div><span className="card-kicker">ACCOUNT</span><h3>Account details</h3></div><ShieldCheck size={17}/></div><div className="profile-line"><div className="avatar large">{(user.displayName||user.email||'U')[0].toUpperCase()}</div><div><b>{user.displayName||'Student'}</b><span>{user.email}</span></div></div><div className="account-info"><span>AUTHENTICATION</span><b>Firebase Authentication</b></div><div className="account-info"><span>WORKSPACE PRIVACY</span><b><span className="live-dot"/> Private to your account</b></div><div className="data-export"><b>Export all progress</b><p>Back up all 90 mission days, journals, to-dos, notes, settings, and attached files in one JSON file.</p><div><button className="primary" onClick={()=>exportData('json')}><Download size={14}/> Export full backup (JSON)</button><button className="secondary compact" onClick={()=>exportData('csv')}>Export CSV summary</button></div></div></section><section className="panel prefs-card"><span className="card-kicker">APPEARANCE</span><h3>Comfortable by default.</h3><p>ENDGAME follows your device appearance and keeps the focus on your study plan.</p><div className="preference-row"><span><Sparkles size={15}/> Appearance</span><b>Follows device</b></div><div className="preference-row"><span><Bell size={15}/> Notifications</span><b>In-app only</b></div><div className="preference-row"><span><LockKeyhole size={15}/> Data residency</span><b>Firebase project</b></div></section></div><footer className="footer"><span>SYSTEM CONFIGURATION <i/> ENDGAME V1.0</span><span>CONFIGURED FOR YOUR MISSION.</span></footer></>}

function TaskModal(p:{initial:Task|null;close:()=>void;save:(d:Partial<Task>)=>void}){const {initial,close,save}=p;const [title,setTitle]=useState(initial?.title||''),[description,setDescription]=useState(initial?.description||''),[dueDate,setDueDate]=useState(initial?.dueDate||''),[priority,setPriority]=useState(initial?.priority||'Normal'),[category,setCategory]=useState(initial?.category||'Study');return <Modal close={close} title={initial?'Edit to-do':'Add a to-do'} kicker="TO-DO LIST"><form className="modal-form" onSubmit={e=>{e.preventDefault();save({title,description,dueDate,priority,category});}}><label className="field-label">TO-DO<input autoFocus required value={title} onChange={e=>setTitle(e.target.value)} placeholder="What do you need to do?"/></label><label className="field-label">DETAILS<textarea rows={3} value={description} onChange={e=>setDescription(e.target.value)} placeholder="Add helpful context..."/></label><div className="form-split"><label className="field-label">DUE DATE<input type="date" value={dueDate} onChange={e=>setDueDate(e.target.value)}/></label><label className="field-label">PRIORITY<select value={priority} onChange={e=>setPriority(e.target.value)}><option>Low</option><option>Normal</option><option>High</option><option>Critical</option></select></label></div><label className="field-label">CATEGORY<select value={category} onChange={e=>setCategory(e.target.value)}>{['Study','Personal','Work','Other'].map(c=><option key={c}>{c}</option>)}</select></label><div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" type="submit">{initial?'Save changes':'Add to-do'} <Check size={15}/></button></div></form></Modal>}function NoteModal(p:{initial:Note|null;close:()=>void;save:(d:{title:string;body:string;pinned:boolean;files:File[]})=>Promise<void>}){const {initial,close,save}=p;const [title,setTitle]=useState(initial?.title||''),[body,setBody]=useState(initial?.body||''),[pinned,setPinned]=useState(initial?.pinned||false),[files,setFiles]=useState<File[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{await save({title,body,pinned,files})}catch(err){setError(err instanceof Error?err.message:'Could not save note')}finally{setBusy(false)}}return <Modal close={close} title={initial?'Edit note':'New note'} kicker="STUDY NOTES"><form className="modal-form" onSubmit={submit}><label className="field-label">NOTE TITLE<input autoFocus required value={title} onChange={e=>setTitle(e.target.value)} placeholder="A name for this thought"/></label><label className="field-label">CONTENT<textarea rows={8} required value={body} onChange={e=>setBody(e.target.value)} placeholder="Capture the detail while it's fresh..."/></label><label className="field-label">ATTACHMENTS <input type="file" multiple onChange={e=>setFiles(Array.from(e.target.files||[]))}/></label>{(initial?.attachments?.length||0)>0&&<div className="attached-list">Already stored: {initial!.attachments!.map((f:Attachment)=>f.name).join(', ')}</div>}{files.length>0&&<div className="attached-list">Selected: {files.map(f=>f.name).join(', ')}</div>}<label className="check-label"><input type="checkbox" checked={pinned} onChange={e=>setPinned(e.target.checked)}/> Pin this note to the archive</label>{error&&<p className="auth-error">{error}</p>}<div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" type="submit" disabled={busy}>{busy?<LoaderCircle className="spin" size={15}/>:null}{initial?'Save changes':'Save note'} <Check size={15}/></button></div></form></Modal>}function Modal(p:{close:()=>void;title:string;kicker:string;children:React.ReactNode}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)p.close()}}><section className="modal"><div className="modal-head"><div><span className="card-kicker">{p.kicker}</span><h2>{p.title}</h2></div><button type="button" aria-label="Close dialog" className="icon-btn" onClick={p.close}><X size={17}/></button></div>{p.children}</section></div>}
